(function(){
const model=window.OfficeModel;const chosen=new Set(['marketing']);let level='essential';const money=n=>'$'+n.toLocaleString('en-US',{minimumFractionDigits:n%1?2:0,maximumFractionDigits:2});
model.departments.forEach(d=>{const label=document.createElement('label');label.className='office-option';label.innerHTML=`<input type="checkbox" value="${d.id}" ${chosen.has(d.id)?'checked':''}><span><strong>${d.name}</strong><small>${d.lead} · ${d.unit} ${d.measure}</small></span><b>${money(d.price)}<small>/ cycle, Essential</small></b>`;label.querySelector('input').onchange=e=>{if(e.target.checked)chosen.add(d.id);else chosen.delete(d.id);render()};document.querySelector('#office-options').append(label)});
model.levels.forEach(l=>{const label=document.createElement('label');label.innerHTML=`<input type="radio" name="office-level" value="${l.id}" ${l.id===level?'checked':''}><span><strong>${l.name}</strong><small>${l.description}</small></span>`;label.querySelector('input').onchange=()=>{level=l.id;render()};document.querySelector('#work-levels').append(label)});
function render(){const r=model.calculate([...chosen],level);const list=r.selected.length?`<ul>${r.selected.map((d,i)=>`<li><b>${d.name}</b><span>${r.allowances[i]}</span></li>`).join('')}</ul>`:'<p>Select at least one department to begin.</p>';document.querySelector('#office-summary').innerHTML=`<h3>${r.selected.length?r.selected.length+' department'+(r.selected.length===1?'':'s'):'Build your office'}</h3><p class="office-total">${money(r.total)}<small> / 28-day cycle</small></p><div class="weekly-price">4 × <b>${money(r.weekly)}</b><span>one payment each week</span></div><p class="fine">${r.level.name} level · proposed allowances per cycle</p>${list}<p class="fine">Allowances are planning examples, not guaranteed launch terms. Maya’s coordination, quality review and an agreed activity summary are included. No unlimited work or instant delivery is implied.</p>`;const text=`PROPOSED OFFICE CONFIGURATION\nDepartments: ${r.selected.map(d=>d.name).join(', ')||'None selected'}\nWork level: ${r.level.name}\nPrice: ${money(r.total)} per 28-day cycle, or 4 weekly payments of ${money(r.weekly)}\nIllustrative allowances:\n${r.allowances.map(a=>'- '+a).join('\n')}\nManaged delivery tools and coordination included within agreed scope. Paid advertising spend is separate.\nChanges take effect at the next weekly boundary after scope and price are confirmed; current-week work remains at its agreed price.\nNo order, payment or integration has been created.`;window.officeSelection={text,...r};document.querySelector('#use-office').disabled=!r.selected.length;document.querySelectorAll('#office-options input').forEach(i=>i.checked=chosen.has(i.value));document.querySelectorAll('#work-levels input').forEach(i=>i.checked=i.value===level)}
const presets=[['Solo essentials',['admin'],'essential'],['Marketing desk',['marketing'],'essential'],['Business support',['admin','finance','research','creative'],'essential'],['Connected office',model.departments.map(d=>d.id),'essential'],['Growing office',model.departments.map(d=>d.id),'growth'],['Extended office',model.departments.map(d=>d.id),'extended']];
presets.forEach(([name,ids,l])=>{const r=model.calculate(ids,l);const a=document.createElement('article');const h=document.createElement('h3');h.textContent=name;const p=document.createElement('p');p.textContent=`${money(r.total)} per cycle · ${money(r.weekly)}/week`;const button=document.createElement('button');button.className='link';button.textContent='Use this starting point ↗';button.onclick=()=>{chosen.clear();ids.forEach(id=>chosen.add(id));level=l;render();document.querySelector('.office-builder').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};a.append(h,p,button);document.querySelector('#office-presets').append(a)});
document.querySelector('#use-office').onclick=()=>{openAssessment();const f=document.querySelector('#brief-form');f.elements.relationship.value='Four weekly payments'};
render();
// Expand each department into a concrete delivery brief and keep all services in the same model.
const grid=document.querySelector('#department-grid');grid.replaceChildren();model.departments.forEach((d,i)=>{const b=document.createElement('button');b.className='department';b.innerHTML=`<span class="department-num">0${i+1} / ${d.lead}</span><h3>${d.name}</h3><p>${d.examples[0]}</p><span class="more">See what your team delivers ↗</span>`;b.onclick=()=>showDetail(d.name,`Led by ${d.lead}. This department supports a defined part of your monthly office package.`,[...d.examples,`Example Essential allowance: ${d.unit} ${d.measure} per 28-day cycle.`,`What we need: ${d.inputs}`,'Every request needs a clear brief and accepted turnaround. Proposed capabilities and allowances remain subject to launch validation.']);grid.append(b)});
})();
